const I = (ingredientId        , quantity        , preparation         )                   => ({ ingredientId, quantity, ...(preparation ? { preparation } : {}) });
const R = (id        , nameZh        , description        , minutes        , ingredients                    , steps          , demoReady = false)         => ({
  id, nameZh, description, servings: 2, minutes, difficulty: minutes <= 25 ? 'easy' : 'medium', ingredients, steps, source: 'built-in', demoReady,
});
const RR = (region        , inspirationUrl        , id        , nameZh        , description        , minutes        , ingredients                    , steps          )         => ({
  ...R(id, nameZh, description, minutes, ingredients, steps), region, inspirationUrls: [inspirationUrl],
});
const RV = (inspirationUrl        , id        , nameZh        , description        , minutes        , ingredients                    , steps          )         => ({
  ...R(id, nameZh, description, minutes, ingredients, steps), inspirationUrls: [inspirationUrl],
});

