export const ingredientById = Object.fromEntries(ingredients.map(x => [x.id, x]))                              ;
export const recipeById = Object.fromEntries(recipes.map(x => [x.id, x]))                          ;
/** B's integration exports. With no filters they return the complete static catalog. */
let customRecipeProvider                              ;
/** D registers a browser-local provider; B never reads localStorage directly. */
export const setCustomRecipeProvider = (provider                 )       => { customRecipeProvider = provider; };
export const getRecipes = ()           => [...recipes, ...(customRecipeProvider?.() ?? [])];
export const getIngredients = ()               => ingredients;
export const getSubstitutions = (recipeId         , ingredientId         )                 => substitutions.filter(x => (!recipeId || x.recipeIds.includes(recipeId)) && (!ingredientId || x.ingredientId === ingredientId));
export const getProducts = (ingredientId         , supermarket                         )            => products.filter(x => (!ingredientId || x.ingredientId === ingredientId) && (!supermarket || x.supermarket === supermarket));
export const getRecipesForIngredient = (ingredientId        )           => getRecipes().filter(x => x.ingredients.some(i => i.ingredientId === ingredientId));
export const getRecipeById = (recipeId        )                     => getRecipes().find(x => x.id === recipeId);
export const featuredSpecialtyRecipeIds = ['mapo-tofu', 'garlic-shoot-pork-rice', 'chive-egg-rice', 'zhacai-chicken-noodles', 'sour-spicy-potatoes', 'shiitake-chicken-noodles', 'sweet-bean-pork-noodles', 'preserved-mustard-tofu-soup'];
export const getFeaturedSpecialtyRecipes = ()           => featuredSpecialtyRecipeIds.map(id => getRecipeById(id)).filter((recipe)                   => Boolean(recipe));
