/** C/D can use this before inventory deduction and whole-pack matching. */
export function resolveSubstitution(line                  , swap              )                     {
  if (line.ingredientId !== swap.ingredientId) throw new Error(`Substitution ${swap.id} does not apply to ${line.ingredientId}`);
  return [
    { ingredientId: swap.replacementId, quantity: line.quantity * swap.quantityRatio },
    ...(swap.extraReplacements ?? []).map(x => ({ ingredientId: x.ingredientId, quantity: line.quantity * x.quantityRatio })),
  ];
}

/** Chinese recipe/ingredient names and English ingredient names/aliases. */
export function searchCatalog(query        )                                                   {
  const term = query.trim().toLocaleLowerCase();
  if (!term) return { recipes: [], ingredients: [] };
  return {
    recipes: getRecipes().filter(x => x.nameZh.toLocaleLowerCase().includes(term)),
    ingredients: ingredients.filter(x => [x.nameZh, x.nameEn, ...x.aliases].some(name => name.toLocaleLowerCase().includes(term))),
  };
}
